export async function openFamilyLink(supabase: SupabaseClient, userId: string): Promise<ExchangeCtx | null> {
  const ctx = await openExchange(supabase, userId);
  if (!ctx) return null;
  return (await isFamilyLinkEnabled(ctx.admin, ctx.orgId)) ? ctx : null;
}

export async function isFamilyLinkEnabled(admin: SupabaseClient, orgId: string): Promise<boolean> {
  const { data, error } = await admin.from('subscriptions').select('family_link_enabled').eq('org_id', orgId).maybeSingle();
  if (error) throw new Error(error.message);
  return (data as { family_link_enabled?: boolean } | null)?.family_link_enabled === true;
}

